// ─────────────────────────────────────────────────────────────────────────────
// Storage adapter. Generated bytes are persisted here and referenced by URL in
// the DB (never base64). `local` writes to /public/generated (dev default);
// `s3` targets any S3-compatible endpoint (R2, B2, MinIO) so the app is
// deployable to read-only serverless hosts.
// ─────────────────────────────────────────────────────────────────────────────

export interface StorageAdapter {
  name: string;
  /** Store bytes under a key, returning a public URL. */
  put(key: string, bytes: Uint8Array, contentType?: string): Promise<string>;
  get(key: string): Promise<Uint8Array | null>;
  delete(key: string): Promise<void>;
}
